#!/usr/bin/env python3
"""Deterministically derive the online runner from Dean's existing H10 collector.

This script does not make design choices. It applies fixed, audited substitutions and
refuses to continue if any expected source anchor is missing.
"""
from __future__ import annotations
import argparse,hashlib
from pathlib import Path

def sha(p:Path)->str:
 h=hashlib.sha256();h.update(p.read_bytes());return h.hexdigest()
def once(text:str, old:str, new:str, label:str)->str:
 n=text.count(old)
 if n!=1: raise RuntimeError(f'{label}: expected exactly one source anchor, found {n}')
 return text.replace(old,new,1)
def main()->int:
 p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
 out=a.source.read_text()
 out=once(out,'"""Guarded real-Isaac SimVLA risk-data collector."""','"""Closed-loop Isaac SimVLA H10 + TopK8 risk argmin-cap online evaluator."""','docstring')
 out=once(out,'WORKSPACE = Path(__file__).resolve().parents[1]','WORKSPACE = Path("/mnt/ai/projects/simvla_isaac_risk_collection_H10_EXECUTION_20260813")','workspace')
 out=once(out,'from risk_collection.runtime_policy import RiskCollectionPlanner, RiskDecisionPlan  # noqa: E402','from online_isaac_runtime import OnlineRiskPlanner, OnlineRiskDecisionPlan, OnlineRiskSelector  # noqa: E402','planner import')
 out=once(out,'rollouts = process_matches("simvla_reaching_rollout.py") + process_matches(\n        "collect_isaac_risk.py"\n    )','rollouts = (\n        process_matches("simvla_reaching_rollout.py")\n        + process_matches("collect_isaac_risk.py")\n        + process_matches("run_isaac_online_risk.py")\n    )','gpu guard')
 out=once(out,'    parser.add_argument("--output-dir", type=Path, required=True)\n','''    parser.add_argument("--output-dir", type=Path, required=True)\n    parser.add_argument("--risk-model-root", type=Path, required=True)\n    parser.add_argument("--risk-normalization", type=Path, required=True)\n    parser.add_argument("--main-threshold", required=True)\n    parser.add_argument("--selected-cap", required=True)\n    parser.add_argument("--online-mode", choices=("shadow", "active"), required=True)\n    parser.add_argument("--online-role", choices=("shadow", "dev", "holdout"), required=True)\n    parser.add_argument("--protocol-id", required=True)\n''','args')
 out=out.replace('plan: RiskDecisionPlan,','plan: OnlineRiskDecisionPlan,')
 out=once(out,'current_plan: RiskDecisionPlan | None = None','current_plan: OnlineRiskDecisionPlan | None = None','plan type')
 out=once(out,'decisions: list[tuple[RiskDecisionPlan, np.ndarray]] = []','decisions: list[tuple[OnlineRiskDecisionPlan, np.ndarray]] = []','decisions type')
 out=once(out,'    inference_only: bool,\n) -> tuple[bool, int]:','    inference_only: bool,\n    selector: OnlineRiskSelector,\n    online_mode: str,\n) -> tuple[bool, int]:','run_episode signature')
 out=once(out,'''    planner = RiskCollectionPlanner(\n        runtime,\n        image_rotation="none",\n        global_seed=int(collection_cfg["policy_sampling_seed"]),\n        source_episode_id=source_episode_id,\n        state_mean=state_mean,\n        state_std=state_std,\n        verify_single_runtime_parity=inference_only,\n    )''','''    planner = OnlineRiskPlanner(\n        runtime,\n        selector=selector,\n        image_rotation="none",\n        global_seed=int(collection_cfg["policy_sampling_seed"]),\n        source_episode_id=source_episode_id,\n        state_mean=state_mean,\n        state_std=state_std,\n        verify_single_runtime_parity=inference_only,\n    )''','planner constructor')
 out=once(out,'''                    current_actions = current_plan.main_chunk_env\n                    current_action_index = 0\n                    current_executed = []''','''                    current_actions = (\n                        current_plan.main_chunk_env\n                        if online_mode == "shadow"\n                        else current_plan.selected_chunk_env\n                    )\n                    current_action_index = 0\n                    current_executed = []''','action selection')
 out=once(out,'''        "current": {"proprio": plan.proprio.tolist()},\n        "parent_episode_outcome": outcome,''','''        "current": {"proprio": plan.proprio.tolist()},\n        "online_risk": {\n            "candidate_scores": plan.candidate_scores.tolist(),\n            "candidate_uncertainty_49d": plan.candidate_uncertainty_49d.tolist(),\n            "selected_candidate_index": int(plan.selection.selected_index),\n            "selection_reason": plan.selection.reason,\n            "main_score": float(plan.selection.main_score),\n            "selected_score": float(plan.selection.selected_score),\n            "best_alternative_index": int(plan.selection.best_alternative_index),\n            "best_alternative_score": float(plan.selection.best_alternative_score),\n            "proposed_modification": bool(plan.selection.proposed_modification),\n            "selected_candidate_action_chunk_normalized": plan.selected_chunk_normalized.tolist(),\n            "selected_candidate_action_chunk_env": plan.selected_chunk_env.tolist(),\n        },\n        "parent_episode_outcome": outcome,''','online row')
 out=once(out,'''        "instruction": episode_plan.spec.instruction,\n        "manifest_fingerprint_sha256": manifest_fingerprint,''','''        "instruction": episode_plan.spec.instruction,\n        "online_policy": "simvla_h10_topk8_argmin_on_alarm_cap",\n        "online_mode": online_mode,\n        "online_action_modifications_count": sum(\n            int(plan.selection.selected_index != 0) for plan, _sequence in decisions\n        ) if online_mode == "active" else 0,\n        "online_proposed_modifications_count": sum(\n            int(plan.selection.proposed_modification) for plan, _sequence in decisions\n        ),\n        "online_changed_decision_indices": [\n            int(plan.decision_index) for plan, _sequence in decisions\n            if online_mode == "active" and plan.selection.selected_index != 0\n        ],\n        "online_first_modification_decision_index": next(\n            (int(plan.decision_index) for plan, _sequence in decisions\n             if online_mode == "active" and plan.selection.selected_index != 0),\n            None,\n        ),\n        "online_risk_main_score_max": max(\n            (float(plan.selection.main_score) for plan, _sequence in decisions),\n            default=0.0,\n        ),\n        "online_risk_selected_score_mean": float(np.mean([\n            float(plan.selection.selected_score) for plan, _sequence in decisions\n        ])) if decisions else 0.0,\n        "manifest_fingerprint_sha256": manifest_fingerprint,''','online summary')
 out=once(out,'''    run_manifest = build_run_manifest(\n        args=args,\n        run_cfg=run_cfg,\n        collection_cfg=collection_cfg,\n        eval_cfg=eval_cfg,\n        raw_manifest=raw_manifest,\n        manifest=manifest,\n        scheduled_benchmark_ids=ordered_benchmark_ids,\n    )\n    store = EpisodeStore(args.output_dir, run_manifest)''','''    run_manifest = build_run_manifest(\n        args=args,\n        run_cfg=run_cfg,\n        collection_cfg=collection_cfg,\n        eval_cfg=eval_cfg,\n        raw_manifest=raw_manifest,\n        manifest=manifest,\n        scheduled_benchmark_ids=ordered_benchmark_ids,\n    )\n    threshold_payload = json.loads((args.risk_model_root / "thresholds.json").read_text())\n    if args.main_threshold not in threshold_payload or args.selected_cap not in threshold_payload:\n        raise RuntimeError("online thresholds must be named entries from seen thresholds.json")\n    run_manifest["online_risk_intervention"] = {\n        "protocol_id": args.protocol_id,\n        "online_mode": args.online_mode,\n        "online_role": args.online_role,\n        "controller": "LIBERO-final-style TopK8 argmin_on_alarm + selected-risk cap",\n        "selection_rule": "argmin_on_alarm",\n        "selection_min_margin": 0.0,\n        "main_threshold_name": args.main_threshold,\n        "main_threshold": float(threshold_payload[args.main_threshold]),\n        "selected_cap_name": args.selected_cap,\n        "selected_score_cap": float(threshold_payload[args.selected_cap]),\n        "risk_model_root": str(args.risk_model_root.resolve()),\n        "risk_model_sha256": sha256_file(args.risk_model_root / "model.pt"),\n        "risk_normalization": str(args.risk_normalization.resolve()),\n        "risk_normalization_sha256": sha256_file(args.risk_normalization),\n        "thresholds_sha256": sha256_file(args.risk_model_root / "thresholds.json"),\n        "detector_threshold_values_are_seen_derived": True,\n        "ood_dev_used_for_controller_pair_selection": args.online_role == "dev",\n        "ood_holdout_used_for_controller_pair_selection": False,\n        "execution_horizon": 10,\n        "candidate_count": 9,\n        "ace_alternative_count": 8,\n        "topk8_indices": list(TOPK8_INDICES),\n    }\n    store = EpisodeStore(args.output_dir, run_manifest)''','run manifest')
 out=once(out,'''    state_std = np.asarray(\n        norm_payload["norm_stats"]["state"]["std"], dtype=np.float32\n    )\n\n    sim = base.sim_utils.SimulationContext(''','''    state_std = np.asarray(\n        norm_payload["norm_stats"]["state"]["std"], dtype=np.float32\n    )\n    selector = OnlineRiskSelector(\n        model_root=args.risk_model_root,\n        normalization_path=args.risk_normalization,\n        main_threshold_name=args.main_threshold,\n        selected_cap_name=args.selected_cap,\n        device=args.device,\n    )\n    if selector.model_sha256 != run_manifest["online_risk_intervention"]["risk_model_sha256"]:\n        raise RuntimeError("risk model changed between manifest creation and load")\n\n    sim = base.sim_utils.SimulationContext(''','selector load')
 out=once(out,'''                    save_video=args.save_video,\n                    inference_only=args.inference_only,\n                )''','''                    save_video=args.save_video,\n                    inference_only=args.inference_only,\n                    selector=selector,\n                    online_mode=args.online_mode,\n                )''','run_episode call')
 out=once(out,'''                            "vlm_encoding_count": current_plan.vlm_encoding_count,\n                            "single_runtime_parity_max_abs": (''','''                            "vlm_encoding_count": current_plan.vlm_encoding_count,\n                            "online_candidate_scores": current_plan.candidate_scores.tolist(),\n                            "online_selected_candidate_index": int(current_plan.selection.selected_index),\n                            "online_selection_reason": current_plan.selection.reason,\n                            "single_runtime_parity_max_abs": (''','inference status')
 a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(out);a.output.chmod(0o755)
 print(f'BASE_COLLECTOR_SHA256={sha(a.source)}')
 print(f'ONLINE_RUNNER_SHA256={sha(a.output)}')
 return 0
if __name__=='__main__':raise SystemExit(main())
